class Common(unittest.TestCase):
    def test_glob(self):
        self.assertTrue(glob_match(".github/workflows/ci.yml", ".github/**"), "a dot-directory is an ordinary path")
        self.assertTrue(glob_match(".env", "**/.env"))
        self.assertTrue(glob_match(".claude/state/x.txt", ".claude/state/**"))
        self.assertTrue(glob_match("./src/a.py", "src/**"), "only a literal ./ prefix is removed")
        self.assertTrue(glob_match("src/a/b.py", "src/**"))
        self.assertTrue(glob_match("x/migrations/1.sql", "**/migrations/**"))
        self.assertTrue(glob_match("a.py", "**/*.py"))
        self.assertTrue(glob_match("deep/a.tsx", "**/*.{jsx,tsx}"))
        self.assertFalse(glob_match("src/a.py", "tests/**"))
        self.assertTrue(glob_match("infra/main.tf", "infra/"))

    def test_frontmatter_subset_parser(self):
        from gates.common import _mini_yaml
        d = _mini_yaml('description: "x"\napplicable_when:\n  phase: [IMPLEMENT, QA]\n  always: true\nlist:\n  - a\n  - b\nn: 3\n')
        self.assertEqual(d["applicable_when"]["phase"], ["IMPLEMENT", "QA"])
        self.assertIs(d["applicable_when"]["always"], True)
        self.assertEqual(d["list"], ["a", "b"])
        self.assertEqual(d["n"], 3)


class Corpus(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.repo = fixture_repo(Path(self.tmp.name))

    def tearDown(self):
        self.tmp.cleanup()

    def test_law_index_parses_both_shapes(self):
        laws = corpus.laws(self.repo)
        u = {l["id"]: l for l in laws["universal"]}
        self.assertEqual(set(u), {"LAW-01", "LAW-02", "LAW-07"})
        self.assertEqual(u["LAW-01"]["body"], ".claude/skills/factory-governance-loading/SKILL.md")
        self.assertEqual(u["LAW-01"]["records"], ["ADR-EVOL-026", "ADR-EVOL-043"])
        self.assertEqual(u["LAW-01"]["sentence"], "Operational law lives in one index and every law has one body.")
        self.assertEqual(u["LAW-07"]["body"], "inline")
        p = {l["id"]: l for l in laws["project"]}
        self.assertEqual(set(p), {"PLAW-01", "PLAW-02"})
        self.assertEqual(p["PLAW-02"]["body"], "rules/stateless.md")

    def test_body_section_resolution(self):
        laws = corpus.laws(self.repo)
        plaw1 = next(l for l in laws["project"] if l["id"] == "PLAW-01")
        f, heading, quoted, body = corpus.body_section(self.repo, plaw1)
        self.assertEqual(f, self.repo / ".claude/rules/architecture.md")
        self.assertEqual(quoted, plaw1["sentence"])
        self.assertIn("body", body)
        plaw2 = next(l for l in laws["project"] if l["id"] == "PLAW-02")
        _, _, quoted2, _ = corpus.body_section(self.repo, plaw2)
        self.assertNotEqual(quoted2, plaw2["sentence"], "the contradicting body must be visible to the parity gate")
        law7 = next(l for l in laws["universal"] if l["id"] == "LAW-07")
        self.assertEqual(corpus.body_section(self.repo, law7), (None, None, None, []))
        self.assertEqual(resolve_pointer(self.repo, "rules/x.md"), self.repo / ".claude/rules/x.md")

    def test_catalog_families_and_classes(self):
        cat = corpus.catalog(self.repo)
        self.assertEqual([f["name"] for f in cat["families"]], ["runtime", "data"])
        self.assertEqual(cat["families"][1]["surface"], ["**/migrations/**", "**/*.sql"])
        self.assertEqual([d["id"] for d in cat["dcs"]], ["DC-18", "DC-27", "DC-29"])
        self.assertEqual(cat["dcs"][1]["gate"], "scripts/validate-migrations.sh")
        self.assertEqual(cat["dcs"][2]["paths"], ["*"])

    def test_resolver_axes(self):
        res = corpus.applicable(self.repo, {"phase": "IMPLEMENT", "command": "implement", "framework": ["fastapi"]})
        names = {r["name"] for r in res["active"]["instructions"]}
        self.assertEqual(names, {"Factory-implement-build"})
        rules = {r["name"] for r in res["active"]["rules"]}
        self.assertIn("architecture.md", rules)
        self.assertIn("protected-code.md", rules, "path_glob resolved against the tracked tree")
        self.assertNotIn("python.md", rules, "framework axis must AND with path_glob")
        ex = {e["name"]: e["reason"] for e in res["excluded"]}
        self.assertTrue(any("frontmatter-parse-error" in v for k, v in ex.items() if k.endswith("broken.md")))
        self.assertTrue(ex[".claude/instructions/Factory-qa-verify.instructions.md"].startswith("phase="))
        self.assertEqual(len(res["active"]["laws"]), 5)
        self.assertEqual(len(res["discovery_hash"]), 8)

    def test_command_axis_with_empty_context_never_raises(self):
        # the pre-edit delivery passes an empty context: an entry whose first axis is `command` must simply not match
        active, why = corpus.matches({"command": ["push"]}, {}, [])
        self.assertFalse(active); self.assertIn("command=push", why)
        text, _ = corpus.digest(self.repo, ["src/app.py"], 6000)
        self.assertIn("DC-18", text)
        self.assertTrue(corpus.matches({"command": ["/implement --build"]}, {"command": "implement"}, [])[0], "documented form matches the command name")
        self.assertTrue(corpus.matches({"command": ["implement"]}, {"command": "/implement --refine"}, [])[0])
        self.assertEqual(corpus.matches({"bogus": ["x"]}, {"phase": "QA"}, [])[1], "applicable-when-invalid: bogus")

    def test_scope_and_change_type_axes(self):
        rules = lambda ctx: {r["name"] for r in corpus.applicable(self.repo, ctx)["active"]["rules"]}
        self.assertIn("React.md", rules({"scope": "frontend-only", "change_type": "feature"}))
        self.assertNotIn("React.md", rules({"scope": "backend-only", "change_type": "feature"}))
        self.assertNotIn("React.md", rules({"scope": "frontend-only", "change_type": "fix"}), "axes AND together")
        self.assertIn("ci-cd.md", rules({}), "path_glob .github/** resolved against the tracked tree")

    def test_excluded_reason_names_the_filter_that_failed(self):
        res = corpus.applicable(self.repo, {"agent": "ARCH"}, ["src/app.py"])
        reasons = {e["name"]: e["reason"] for e in res["excluded"]}
        self.assertEqual(reasons["DC-18"], "agent not in applicable_to")
        self.assertEqual(reasons["DC-27"], "paths/family do not match")

    def test_discovery_hash_covers_laws_and_classes(self):
        before = corpus.applicable(self.repo, {"phase": "QA"})["discovery_hash"]
        cat = self.repo / ".claude/rules/defect-prevention.md"
        cat.write_text(cat.read_text() + "| DC-30 | `runtime` | A new class. | `—` | `src/**` | DEV | WARNING |\n", encoding="utf-8")
        self.assertNotEqual(before, corpus.applicable(self.repo, {"phase": "QA"})["discovery_hash"], "a new DC changes the roll-call hash")

    def test_catalog_shape_is_fail_closed(self):
        cat = self.repo / ".claude/rules/defect-prevention.md"
        base = cat.read_text()
        cat.write_text(base + "| DC-31 | `runtime` | six columns | `—` | `src/**` | DEV |\n", encoding="utf-8")
        with self.assertRaisesRegex(GateFault, "DC-31 has 6 columns"):
            corpus.catalog(self.repo)
        cat.write_text(base + "| DC-32 | `ghost` | unknown family | `—` | `src/**` | DEV | WARNING |\n", encoding="utf-8")
        with self.assertRaisesRegex(GateFault, "family `ghost`"):
            corpus.catalog(self.repo)
        cat.write_text(base + "| DC-33 | `runtime` | no paths | `—` | — | DEV | WARNING |\n", encoding="utf-8")
        with self.assertRaisesRegex(GateFault, "no Paths"):
            corpus.catalog(self.repo)

    def test_law_without_pointer_is_refused_and_records_read_after_pointer(self):
        with self.assertRaisesRegex(GateFault, "no `Body:` pointer"):
            corpus.parse_law_list("## Governance Rules\n1. **[LAW-99] X** — S.\n## Y\n")
        with self.assertRaisesRegex(GateFault, "pre-index law shape"):
            corpus.parse_law_list("## Governance Rules\n1. **[LAW-99] X**: old shape body.\n## Y\n")
        s, b, r = corpus._entry_from_rest("Sentence mentions Records: nothing. Body: `inline`. Records: `ADR-1`.")
        self.assertEqual((b, r), ("inline", ["ADR-1"]))
        self.assertTrue(s.startswith("Sentence mentions Records: nothing"))
        pairs = corpus.law_sentences("## Governance Rules\n1. **[LAW-99] X** — No pointer here.\n## Y\n")
        self.assertEqual(pairs, [("LAW-99", "No pointer here.")], "the ceremony gate still sees the sentence of a malformed entry")

    def test_parity_finds_every_way_a_body_can_lie(self):
        problems = corpus.parity(self.repo)
        self.assertTrue(any(p.startswith("PLAW-02") and "differs" in p for p in problems), "contradicting quote")
        write(self.repo / ".claude/rules/dup.md", "---\ndescription: d\napplicable_when:\n  always: true\n---\n## [PLAW-01] KISS & DRY\n> Every solution is the simplest one that satisfies the specification, written once.\n")
        write(self.repo / ".claude/rules/orphan.md", "---\ndescription: o\napplicable_when:\n  always: true\n---\n## [PLAW-09] Ghost\n> A body with no index entry.\n")
        problems = corpus.parity(self.repo)
        self.assertTrue(any("PLAW-01: 2 body sections" in p for p in problems), "one body per law")
        self.assertTrue(any("PLAW-09" in p and "orphan" in p for p in problems))
        (self.repo / ".claude/rules/stateless.md").unlink()
        self.assertTrue(any("PLAW-02" in p and "does not resolve" in p for p in corpus.parity(self.repo)))

    def test_resolver_by_paths(self):
        res = corpus.applicable(self.repo, {}, ["src/app.py"])
        self.assertEqual([f["name"] for f in res["active"]["families"]], ["runtime"])
        self.assertEqual({d["id"] for d in res["active"]["dcs"]}, {"DC-18", "DC-29"})
        res = corpus.applicable(self.repo, {}, ["src/migrations/001.sql"])
        self.assertEqual({f["name"] for f in res["active"]["families"]}, {"runtime", "data"})
        self.assertIn("DC-27", {d["id"] for d in res["active"]["dcs"]})
        res = corpus.applicable(self.repo, {"agent": "ARCH"}, ["src/app.py"])
        self.assertEqual({d["id"] for d in res["active"]["dcs"]}, set(), "applicable_to filters by agent")

    def test_rollcall_shape(self):
        text = corpus.rollcall(corpus.applicable(self.repo, {"phase": "QA"}), "qa", "FEAT-1")
        for needle in ("📋 Applicability Roll-Call — qa · FEAT-1", "ACTIVE LAWS (5)", "ACTIVE DCs", "UNREADABLE (1)", "broken.md", "EXCLUDED (", "Discovery hash:"):
            self.assertIn(needle, text)

    def test_digest_respects_budget_in_bytes(self):
        full, fp_full = corpus.digest(self.repo, ["src/app.py", "src/migrations/001.sql"], 6000)
        self.assertIn("family runtime", full)
        self.assertIn("DC-27", full)
        self.assertIn("read .claude/rules/protected-code.md", full, "path-bound rule pointer for the .py file")
        self.assertNotIn("architecture.md", full, "always-rules are in the snapshot, not re-delivered")
        self.assertIn("rule .claude/rules/broken.md unreadable", full, "an unreadable rule is said, never silently dropped")
        cat = self.repo / ".claude/rules/defect-prevention.md"
        cat.write_text(cat.read_text() + "| DC-40 | `runtime` | " + "— multibyte dashes — " * 12 + " | `—` | `src/**` | DEV | WARNING |\n", encoding="utf-8")
        for b in list(range(150, 420, 37)) + [60]:   # 60 < the head with its attributes: the envelope drops them and still fits
            text, _ = corpus.digest(self.repo, ["src/migrations/001.sql"], b)
            self.assertLessEqual(len(text.encode()), b, f"budget {b} is in bytes")
            self.assertTrue(text.startswith("<governance-at-edit") and text.endswith("</governance-at-edit>"))
        text, _ = corpus.digest(self.repo, ["src/app.py"], 400)
        self.assertIn("more — read", text, "what was cut is counted, never silent")
        _, fp_a = corpus.digest(self.repo, ["src/a.py"], 6000)
        _, fp_b = corpus.digest(self.repo, ["src/b.py"], 6000)
        self.assertEqual(fp_a, fp_b, "the same delivered set dedupes across paths")


class Retired(unittest.TestCase):
    def test_ratchet_red_and_exemptions(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = fixture_repo(Path(tmp))
            hits = retired.scan(repo)
            paths = {h["path"] for h in hits}
            self.assertIn("docs/old.md", paths, "a retired term in the governed tree is red")
            self.assertNotIn("docs/legacy/x.md", paths, "declared exemption glob")
            self.assertNotIn("docs/project_log/evolutions/ADR-1.md", paths, "history is exempt by class")
            self.assertNotIn("config/quality.json", paths, "the declaration itself is exempt")
            self.assertIn("FAIL", retired.render(hits))
            (repo / "docs/old.md").write_text("clean\n", encoding="utf-8")
            self.assertEqual(retired.scan(repo), [])
            write(repo / "src/note.md", f"{RETIRED} in src\n")
            write(repo / "vendor/x.lock", f"{RETIRED} in a lock\n")
            subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
            self.assertIn("src/note.md", {h["path"] for h in retired.scan(repo)})
            (repo / "config/coherence-context.json").write_text(json.dumps({"context": "downstream", "audit": {"root_sets": ["docs/"], "exclusions": ["*.lock"]}}), encoding="utf-8")
            self.assertEqual({h["path"] for h in retired.scan(repo)}, set(), "roots limit the scan; *.lock excluded")
            (repo / "config/quality.json").write_text(json.dumps({"retired_terms": [{"term": "x"}]}), encoding="utf-8")
            with self.assertRaisesRegex(GateFault, "needs `term` and `record`"):
                retired.scan(repo)


class Budget(unittest.TestCase):
    def test_missing_key_is_a_red_verdict_and_corrupt_config_a_fault(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = fixture_repo(Path(tmp))
            (repo / "config/quality.json").write_text("{}", encoding="utf-8")
            rows = budget.measure(repo)
            self.assertTrue(all(not r["ok"] and "missing" in r["fault"] for r in rows.values()), "every missing key is a red row")
            with self.assertRaises(GateFault):
                key(repo, "budgets", required=True)
            (repo / "config/quality.json").write_text("{not json", encoding="utf-8")
            with self.assertRaisesRegex(GateFault, "not readable JSON"):
                budget.measure(repo)

    def test_measures_real_producers_and_flags_overflow(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = fixture_repo(Path(tmp))
            write(repo / "scripts/validate-governance.sh", "#!/usr/bin/env bash\n[ \"$1\" = --banner ] && printf 'Governance loaded: x\\n'\n")
            write(repo / "scripts/governance-onprompt.sh", "#!/usr/bin/env bash\n[ \"${GOVERNANCE_ONPROMPT_WORST_CASE:-}\" = 1 ] && head -c 20000 /dev/zero | tr '\\0' 'y'\nexit 0\n")
            import shutil; shutil.copytree(HERE, repo / "scripts/gates", ignore=shutil.ignore_patterns("__pycache__", "test_*"))
            shutil.copy(HERE.parent / "gate.py", repo / "scripts/gate.py")
            write(repo / ".claude/hooks/deliver-governance.sh", "#!/usr/bin/env bash\npython3 scripts/gate.py --repo . deliver --hook-json\n")   # the REAL delivery, so the dedupe pointer would be measurable
            write(repo / ".context/governance_snapshot.md", "x" * 100)
            rows = budget.measure(repo)
            self.assertEqual(rows["session_start"]["bytes"], len("Governance loaded: x\n"))
            self.assertTrue(rows["session_start"]["ok"])
            self.assertEqual(rows["prompt_submit"]["bytes"], 20000)
            self.assertFalse(rows["prompt_submit"]["ok"], "the real producer overflowed its key — red")
            self.assertEqual(rows["snapshot"]["bytes"], 100)
            self.assertIn("OVERFLOW", budget.render(rows))
            cat = corpus.catalog(repo)
            self.assertEqual(budget.worst_case_path(cat), "src/x/migrations/x/x.py", "the path under the most globs at once")
            tie = {"families": [{"name": "a", "surface": ["**/*.zz"], "invariant": "x"}, {"name": "b", "surface": ["**/*.aa"], "invariant": "y"}], "dcs": []}
            self.assertEqual(budget.worst_case_path(tie), "x/x.aa", "equal scores resolve to the sorted-first candidate, every run")
            self.assertGreater(rows["pre_edit"]["bytes"], 150, "the real payload was measured")
            self.assertEqual(rows["pre_edit"]["bytes"], budget.measure(repo)["pre_edit"]["bytes"], "a fresh session per run: never the dedupe pointer")
            self.assertFalse(list((repo / ".claude/state").glob("governance-delivered-budget-*")), "no marker left behind")
            write(repo / ".claude/hooks/deliver-governance.sh", "#!/usr/bin/env bash\nexit 0\n")
            rows = budget.measure(repo)
            self.assertFalse(rows["pre_edit"]["ok"], "an empty pre-edit delivery is a dead producer, never within budget")
            self.assertIn("EMPTY", budget.render(rows))
            write(repo / "scripts/validate-governance.sh", "#!/usr/bin/env bash\necho boom >&2\nexit 1\n")
            rows = budget.measure(repo)
            self.assertFalse(rows["session_start"]["ok"]); self.assertIn("exited 1: boom", rows["session_start"]["fault"])
            self.assertIn("RED — producer", budget.render(rows))
            (repo / "scripts/governance-onprompt.sh").unlink()
            rows = budget.measure(repo)
            self.assertFalse(rows["prompt_submit"]["ok"]); self.assertIn("producer absent", rows["prompt_submit"]["fault"])
            (repo / "config/quality.json").write_text(json.dumps({"budgets": {"session_start": 1}}), encoding="utf-8")
            rows = budget.measure(repo)
            self.assertFalse(rows["pre_edit"]["ok"]); self.assertIn("key budgets.pre_edit missing", rows["pre_edit"]["fault"])


class Coherence(unittest.TestCase):
    def _repo(self, tmp):
        repo = fixture_repo(Path(tmp))
        # the review-hash pipeline the diff subject delegates to (real scripts, copied)
        for rel in (".claude/skills/factory-pr-review/scripts/detect_change_type.py", ".claude/skills/factory-code-review/scripts/code_review_hash.py"):
            src = HERE.parent.parent / rel
            if src.is_file():
                write(repo / rel, src.read_text(encoding="utf-8"))
        subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "pipeline"], check=True)
        return repo

    def test_certify_tree_moves_with_the_subject(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            h1 = coherence.certify(repo, "tree", paths=["src/**"])
            self.assertEqual(h1, coherence.certify(repo, "tree", paths=["src/**"]), "deterministic")
            write(repo / "docs/x.md", "docs only\n"); subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
            self.assertEqual(h1, coherence.certify(repo, "tree", paths=["src/**"]), "a change outside the paths does not move the subject")
            write(repo / "src/app.py", "print(2)\n"); subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
            self.assertNotEqual(h1, coherence.certify(repo, "tree", paths=["src/**"]), "a change under the paths moves the subject")
            with self.assertRaisesRegex(GateFault, "needs the paths"):
                coherence.certify(repo, "tree")
            with self.assertRaisesRegex(GateFault, "unknown certification subject"):
                coherence.certify(repo, "blob")

    def test_currency_stale_missing_fresh_unreadable(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            fresh = coherence.certify(repo, "tree", paths=["src/**"])
            write(repo / "docs/spec/F/qa/qa_report_final_1.md", f"---\nstatus: APPROVED\nverdict: APPROVED\ncertifies:\n  subject: tree\n  paths: [\"src/**\"]\n  hash: \"{fresh}\"\n---\n")
            write(repo / "docs/spec/F/qa/qa_report_draft.md", "---\nstatus: DRAFT\n---\n")            # not terminal: no certification owed
            write(repo / "docs/spec/F/review/peer_review_1.md", "---\nstatus: APPROVED\n---\n")       # terminal, no certifies
            write(repo / "docs/spec/F/smoke_e2e_report.md", "---\noverall_verdict: PASS\ncertifies: [broken\n---\n")
            subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
            reasons = {f["path"]: f["reason"] for f in coherence.currency(repo)}
            self.assertNotIn("docs/spec/F/qa/qa_report_final_1.md", reasons, "fresh certification is green")
            self.assertNotIn("docs/spec/F/qa/qa_report_draft.md", reasons)
            self.assertIn("certifies-missing", reasons["docs/spec/F/review/peer_review_1.md"])
            self.assertIn("unreadable", reasons["docs/spec/F/smoke_e2e_report.md"])
            write(repo / "src/app.py", "print(3)\n"); subprocess.run(["git", "-C", str(repo), "add", "-A"], check=True)
            reasons = {f["path"]: f["reason"] for f in coherence.currency(repo)}
            self.assertIn("STALE", reasons["docs/spec/F/qa/qa_report_final_1.md"], "the build moved under the verdict")
            self.assertIn("FAIL", coherence.render("currency", coherence.currency(repo)))

    def test_manifest_parity_red_on_drift_and_unreadable(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = self._repo(tmp)
            write(repo / "config/coherence-context.json", json.dumps({"context": "downstream", "audit": {"manifest_paths": {"primary": "docs/project_log/governance_versions.json"}}}))
            write(repo / "docs/project_log/governance_versions.json", json.dumps({"templates": {
                "rules/architecture.md": {"version": "1.2.0", "target": ".claude/rules/architecture.md"},
                "rules/stateless.md": {"version": "1.0.0", "target": ".claude/rules/stateless.md"},
                "rules/broken.md": {"version": "1.0.0", "target": ".claude/rules/broken.md"}}}))
            write(repo / ".claude/rules/architecture.md", "---\nversion: 1.1.0\napplicable_when:\n  always: true\n---\n")
            write(repo / ".claude/rules/stateless.md", "---\nversion: 1.0.0\napplicable_when:\n  always: true\n---\n")
            reasons = {f["path"]: f["reason"] for f in coherence.manifest_parity(repo)}
            self.assertIn("1.1.0 ≠ manifest 1.2.0", reasons[".claude/rules/architecture.md"])
            self.assertNotIn(".claude/rules/stateless.md", reasons)
            self.assertIn("unreadable", reasons[".claude/rules/broken.md"])
            (repo / "docs/project_log/governance_versions.json").write_text("{nope", encoding="utf-8")
            with self.assertRaisesRegex(GateFault, "not readable JSON"):
                coherence.manifest_parity(repo)


class Cli(unittest.TestCase):
    def test_cli_exit_codes(self):
        with tempfile.TemporaryDirectory() as tmp:
            repo = fixture_repo(Path(tmp))
            gate = str(HERE.parent / "gate.py")
            env = {**os.environ, "PYTHONDONTWRITEBYTECODE": "1"}
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "retired-terms"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1)
            self.assertIn("docs/old.md", r.stdout)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "key", "nope.key", "--required"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 2)
            self.assertIn("missing", r.stderr)
            self.assertNotIn("Traceback", r.stderr)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "deliver", "--path", "src/app.py", "--session", "s"], capture_output=True, text=True, env=env)
            env_out = json.loads(r.stdout)
            self.assertEqual(env_out["hookSpecificOutput"]["hookEventName"], "PreToolUse")
            self.assertIn("DC-18", env_out["hookSpecificOutput"]["additionalContext"])
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "deliver", "--hook-json"], input=json.dumps({"tool_input": {"file_path": "src/app.py"}, "session_id": "h"}), capture_output=True, text=True, env=env)
            self.assertIn("DC-18", json.loads(r.stdout)["hookSpecificOutput"]["additionalContext"])
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "deliver", "--hook-json"], input="{not json", capture_output=True, text=True, env=env)
            self.assertEqual((r.returncode, r.stdout), (0, ""), "malformed hook payload: silent pass")
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "laws", "--parity"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1); self.assertIn("PLAW-02", r.stdout)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "manifest-parity"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 2, "no manifest at all is a fault, never a pass")
            write(repo / "docs/project_log/governance_versions.json", json.dumps({"templates": {"rules/architecture.md": {"version": "1.0.0", "target": ".claude/rules/architecture.md"}}}))
            write(repo / ".claude/rules/architecture.md", "---\nversion: 1.0.0\napplicable_when:\n  always: true\n---\n## [PLAW-01] KISS & DRY\n> Every solution is the simplest one that satisfies the specification, written once.\n\nbody\n")
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "manifest-parity"], capture_output=True, text=True, env=env)
            self.assertEqual((r.returncode, r.stdout.strip()), (0, "manifest-parity: ok"), r.stdout + r.stderr)
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "currency"], capture_output=True, text=True, env=env)
            self.assertEqual((r.returncode, r.stdout.strip()), (0, "currency: ok"))
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "law-sentences", "--file", str(repo / "CLAUDE.md")], capture_output=True, text=True, env=env)
            self.assertIn("LAW-02\tNever modify protected code.", r.stdout)
            broken = Path(tmp) / "broken"; broken.mkdir(); (broken / "gate.py").write_text(Path(gate).read_text(), encoding="utf-8")
            r = subprocess.run([sys.executable, str(broken / "gate.py"), "--repo", str(repo), "context"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 2); self.assertIn("package is missing or broken", r.stderr); self.assertNotIn("Traceback", r.stderr)
            import shutil; shutil.copytree(HERE, broken / "gates", ignore=shutil.ignore_patterns("__pycache__", "test_*"))
            (broken / "gates" / "common.py").write_text("def (broken syntax\n", encoding="utf-8")
            r = subprocess.run([sys.executable, str(broken / "gate.py"), "--repo", str(repo), "context"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 2); self.assertIn("SyntaxError", r.stderr); self.assertNotIn("Traceback", r.stderr)
            write(repo / "scripts/validate-governance.sh", "#!/usr/bin/env bash\nexit 3\n")
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "budget"], capture_output=True, text=True, env=env)
            self.assertEqual(r.returncode, 1, "a dead producer is a red verdict, exit 1")
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "snapshot-sections"], capture_output=True, text=True, env=env)
            self.assertIn("### [PLAW-01] KISS & DRY", r.stdout)
            self.assertIn("| `runtime` |", r.stdout)
            self.assertIn("runtime: Python", r.stdout, "stack configuration comes from the one reader")
            self.assertIn("| python.md | {", r.stdout, "rules manifest comes from the one reader")
            self.assertNotIn("Law Bodies", r.stdout)
            const = repo / "docs/constitution.md"
            const.write_text(const.read_text().replace("Body: `rules/stateless.md`", "Body: `rules/python.md`"), encoding="utf-8")  # a file without the heading
            r = subprocess.run([sys.executable, gate, "--repo", str(repo), "snapshot-sections", "--profile", "full"], capture_output=True, text=True, env=env)
            self.assertIn("Law Bodies", r.stdout)
            self.assertIn("DC-27", r.stdout)
            self.assertIn("### [PLAW-02] → rules/python.md  (body section not found)", r.stdout)


